{
  "candidates": [
    {
      "claimType": "preference",
      "statement": "该用户近期主动尝试并倾向于维持素食饮食模式。",
      "supportingRefs": [
        "o1",
        "o2",
        "o3"
      ],
      "alternativeExplanations": [
        "因短期健康原因（如肠胃不适、体检指标异常）而进行的临时性饮食调整，而非长期偏好。",
        "受外部因素（如特定促销活动、食材获取困难或社交圈影响）导致的被动选择。"
      ],
      "verificationPlan": [
        {
          "op": "checkCoverage",
          "question": "近1个月内的外卖订单中是否完全剔除了肉类？自炊采购为零是否意味着所有肉类摄入都来自外卖或他人提供？"
        },
        {
          "op": "searchCounterEvidence",
          "question": "查找过去3-6个月的饮食记录，确认这是突发性的短期行为还是长期趋势的延续？"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现仅为短期应对身体不适或外部限制，则从「偏好」降级为「临时状态」或「情境性行为」。",
      "evidenceGrade": "支持",
      "action": "adopt"
    },
    {
      "claimType": "recurringBehavior",
      "statement": "该用户在近一个月内显著减少了外卖中的肉类消费频率。",
      "supportingRefs": [
        "o1"
      ],
      "alternativeExplanations": [
        "外卖平台推荐算法改变导致用户看到的素食选项增多，从而改变了点击/购买习惯。",
        "用户在外卖之外有其他主要的肉类摄入渠道（如食堂、聚餐），因此外卖占比变化不代表总摄入量变化。"
      ],
      "verificationPlan": [
        {
          "op": "compareConditions",
          "question": "对比前2个月与近1个月的外卖平台首页推荐内容或搜索历史，排除算法干扰。"
        },
        {
          "op": "retrieveRelated",
          "question": "检索同期的其他餐饮场景（如公司食堂、家庭聚餐）记录，评估整体肉类摄入量的变化。"
        }
      ],
      "whatWouldChangeTheAnswer": "若发现其他场景肉类摄入未减，则该命题仅适用于「外卖场景」而非整体饮食行为。",
      "evidenceGrade": "线索",
      "action": "observe"
    }
  ]
}
